  1→package handler
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"io"
  7→	"log/slog"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→	"sort"
 12→	"strings"
 13→	"time"
 14→
 15→	"github.com/modelcontextprotocol/go-sdk/mcp"
 16→	"github.com/nsega/mcp-obsidian/internal/note"
 17→	"github.com/nsega/mcp-obsidian/internal/vault"
 18→)
 19→
 20→// Handler holds the vault reference and provides MCP tool handler methods
 21→type Handler struct {
 22→	vault  *vault.Vault
 23→	logger *slog.Logger
 24→}
 25→
 26→// New creates a new Handler with the given Vault and Logger
 27→func New(v *vault.Vault, logger *slog.Logger) *Handler {
 28→	if logger == nil {
 29→		logger = slog.New(slog.NewTextHandler(io.Discard, nil))
 30→	}
 31→	return &Handler{vault: v, logger: logger}
 32→}
 33→
 34→// SearchNotes implements the search_notes tool
 35→func (h *Handler) SearchNotes(ctx context.Context, req *mcp.CallToolRequest, input note.SearchNotesInput) (*mcp.CallToolResult, note.SearchNotesOutput, error) {
 36→	var results []string
 37→	query := input.Query
 38→
 39→	// Try to compile as regex, if it fails, use literal string matching
 40→	var re *regexp.Regexp
 41→	var useRegex bool
 42→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
 43→		re = compiled
 44→		useRegex = true
 45→	}
 46→
 47→	// Walk through the vault directory
 48→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
 49→		if err != nil {
 50→			h.logger.Debug("skipping path", "path", path, "error", err)
 51→			return nil
 52→		}
 53→
 54→		// Skip directories
 55→		if info.IsDir() {
 56→			// Check if directory is allowed (not hidden)
 57→			allowed, checkErr := h.vault.IsPathAllowed(path)
 58→			if checkErr != nil || !allowed {
 59→				return filepath.SkipDir
 60→			}
 61→			return nil
 62→		}
 63→
 64→		// Only process markdown files
 65→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
 66→			return nil
 67→		}
 68→
 69→		// Check if file is allowed
 70→		allowed, checkErr := h.vault.IsPathAllowed(path)
 71→		if checkErr != nil || !allowed {
 72→			return nil
 73→		}
 74→
 75→		// Get filename
 76→		filename := filepath.Base(path)
 77→
 78→		// Match against query
 79→		matched := false
 80→		if useRegex {
 81→			matched = re.MatchString(filename)
 82→		} else {
 83→			matched = strings.Contains(strings.ToLower(filename), strings.ToLower(query))
 84→		}
 85→
 86→		if matched {
 87→			results = append(results, path)
 88→			// Limit results
 89→			if len(results) >= vault.MaxSearchResults {
 90→				return filepath.SkipAll
 91→			}
 92→		}
 93→
 94→		return nil
 95→	})
 96→
 97→	if err != nil {
 98→		return nil, note.SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
 99→	}
100→
101→	output := note.SearchNotesOutput{
102→		Results: results,
103→	}
104→
105→	// Create text content for the result
106→	textContent := fmt.Sprintf("Found %d matching notes", len(results))
107→	if len(results) > 0 {
108→		textContent += ":\n" + strings.Join(results, "\n")
109→	}
110→
111→	result := &mcp.CallToolResult{
112→		Content: []mcp.Content{
113→			&mcp.TextContent{
114→				Text: textContent,
115→			},
116→		},
117→	}
118→
119→	return result, output, nil
120→}
121→
122→// ReadNotes implements the read_notes tool
123→func (h *Handler) ReadNotes(ctx context.Context, req *mcp.CallToolRequest, input note.ReadNotesInput) (*mcp.CallToolResult, note.ReadNotesOutput, error) {
124→	notes := make([]note.NoteContent, 0, len(input.Paths))
125→
126→	for _, path := range input.Paths {
127→		n := note.NoteContent{
128→			Path: path,
129→		}
130→
131→		// Check if path is allowed
132→		allowed, err := h.vault.IsPathAllowed(path)
133→		if err != nil {
134→			n.Error = fmt.Sprintf("Path validation error: %v", err)
135→			notes = append(notes, n)
136→			continue
137→		}
138→
139→		if !allowed {
140→			n.Error = "Access denied: path is outside vault or is a hidden file"
141→			notes = append(notes, n)
142→			continue
143→		}
144→
145→		// Read file content
146→		content, err := os.ReadFile(path)
147→		if err != nil {
148→			n.Error = fmt.Sprintf("Failed to read file: %v", err)
149→			notes = append(notes, n)
150→			continue
151→		}
152→
153→		n.Content = string(content)
154→		notes = append(notes, n)
155→	}
156→
157→	output := note.ReadNotesOutput{
158→		Notes: notes,
159→	}
160→
161→	// Create text content for the result
162→	var textParts []string
163→	for _, n := range notes {
164→		if n.Error != "" {
165→			textParts = append(textParts, fmt.Sprintf("## %s\nError: %s", n.Path, n.Error))
166→		} else {
167→			textParts = append(textParts, fmt.Sprintf("## %s\n%s", n.Path, n.Content))
168→		}
169→	}
170→
171→	result := &mcp.CallToolResult{
172→		Content: []mcp.Content{
173→			&mcp.TextContent{
174→				Text: strings.Join(textParts, "\n\n"),
175→			},
176→		},
177→	}
178→
179→	return result, output, nil
180→}
