182→// CreateNote implements the create_note tool
183→func (h *Handler) CreateNote(ctx context.Context, req *mcp.CallToolRequest, input note.CreateNoteInput) (*mcp.CallToolResult, note.CreateNoteOutput, error) {
184→	if input.Title == "" {
185→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title is required")
186→	}
187→
188→	slug := note.Slugify(input.Title)
189→	if slug == "" {
190→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
191→	}
192→
193→	today := time.Now().Format("2006-01-02")
194→	filename := today + "_" + slug + ".md"
195→
196→	dir := h.vault.Path
197→	if input.Folder != "" {
198→		dir = filepath.Join(h.vault.Path, input.Folder)
199→	}
200→
201→	fullPath := filepath.Join(dir, filename)
202→
203→	allowed, err := h.vault.IsPathAllowed(fullPath)
204→	if err != nil {
205→		return nil, note.CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
206→	}
207→	if !allowed {
208→		return nil, note.CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
209→	}
210→
211→	if _, err := os.Stat(fullPath); err == nil {
212→		return nil, note.CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
213→	}
214→
215→	if err := os.MkdirAll(dir, 0755); err != nil {
216→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
217→	}
218→
219→	frontmatter := note.GenerateFrontmatter(input.Tags, today, today)
220→
221→	var content strings.Builder
222→	content.WriteString(frontmatter)
223→	content.WriteString("\n# ")
224→	content.WriteString(input.Title)
225→	content.WriteByte('\n')
226→	if input.Content != "" {
227→		content.WriteByte('\n')
228→		content.WriteString(input.Content)
229→		content.WriteByte('\n')
230→	}
231→
232→	if err := os.WriteFile(fullPath, []byte(content.String()), 0644); err != nil {
233→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
234→	}
235→
236→	output := note.CreateNoteOutput{Path: fullPath}
237→	result := &mcp.CallToolResult{
238→		Content: []mcp.Content{
239→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
240→		},
241→	}
242→	return result, output, nil
243→}
