245→// UpdateNote implements the update_note tool
246→func (h *Handler) UpdateNote(ctx context.Context, req *mcp.CallToolRequest, input note.UpdateNoteInput) (*mcp.CallToolResult, note.UpdateNoteOutput, error) {
247→	allowed, err := h.vault.IsPathAllowed(input.Path)
248→	if err != nil {
249→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
250→	}
251→	if !allowed {
252→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
253→	}
254→
255→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
256→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
257→	}
258→
259→	mode := input.Mode
260→	if mode == "" {
261→		mode = "replace"
262→	}
263→
264→	switch mode {
265→	case "replace":
266→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
267→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
268→		}
269→	case "append":
270→		existing, err := os.ReadFile(input.Path)
271→		if err != nil {
272→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to read file: %w", err)
273→		}
274→		newContent := string(existing) + "\n\n" + input.Content
275→		if err := os.WriteFile(input.Path, []byte(newContent), 0644); err != nil {
276→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
277→		}
278→	default:
279→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
280→	}
281→
282→	output := note.UpdateNoteOutput{Path: input.Path}
283→	result := &mcp.CallToolResult{
284→		Content: []mcp.Content{
285→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
286→		},
287→	}
288→	return result, output, nil
289→}
