329→// SearchContent implements the search_content tool
330→func (h *Handler) SearchContent(ctx context.Context, req *mcp.CallToolRequest, input note.SearchContentInput) (*mcp.CallToolResult, note.SearchContentOutput, error) {
331→	query := input.Query
332→
333→	var re *regexp.Regexp
334→	var useRegex bool
335→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
336→		re = compiled
337→		useRegex = true
338→	}
339→
340→	var results []note.ContentMatch
341→
342→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
343→		if err != nil {
344→			h.logger.Debug("skipping path", "path", path, "error", err)
345→			return nil
346→		}
347→
348→		if info.IsDir() {
349→			allowed, checkErr := h.vault.IsPathAllowed(path)
350→			if checkErr != nil || !allowed {
351→				return filepath.SkipDir
352→			}
353→			return nil
354→		}
355→
356→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
357→			return nil
358→		}
359→
360→		allowed, checkErr := h.vault.IsPathAllowed(path)
361→		if checkErr != nil || !allowed {
362→			return nil
363→		}
364→
365→		data, err := os.ReadFile(path)
366→		if err != nil {
367→			h.logger.Debug("skipping unreadable file", "path", path, "error", err)
368→			return nil
369→		}
370→
371→		lines := strings.Split(string(data), "\n")
372→		for lineNum, line := range lines {
373→
374→			matched := false
375→			if useRegex {
376→				matched = re.MatchString(line)
377→			} else {
378→				matched = strings.Contains(strings.ToLower(line), strings.ToLower(query))
379→			}
380→
381→			if matched {
382→				results = append(results, note.ContentMatch{
383→					Path:    path,
384→					Snippet: line,
385→					Line:    lineNum + 1,
386→				})
387→				if len(results) >= vault.MaxSearchResults {
388→					return filepath.SkipAll
389→				}
390→			}
391→		}
392→
393→		return nil
394→	})
395→
396→	if err != nil {
397→		return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
398→	}
399→
400→	output := note.SearchContentOutput{Results: results}
401→
402→	textContent := fmt.Sprintf("Found %d matching lines", len(results))
403→	if len(results) > 0 {
404→		var lines []string
405→		for _, m := range results {
406→			lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
407→		}
408→		textContent += ":\n" + strings.Join(lines, "\n")
409→	}
410→
411→	result := &mcp.CallToolResult{
412→		Content: []mcp.Content{
413→			&mcp.TextContent{Text: textContent},
414→		},
415→	}
416→	return result, output, nil
417→}
