419→// GetBacklinks implements the get_backlinks tool
420→func (h *Handler) GetBacklinks(ctx context.Context, req *mcp.CallToolRequest, input note.GetBacklinksInput) (*mcp.CallToolResult, note.GetBacklinksOutput, error) {
421→	if input.NoteName == "" {
422→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("note_name is required")
423→	}
424→
425→	noteName := strings.TrimSuffix(input.NoteName, ".md")
426→	wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
427→
428→	var results []note.Backlink
429→
430→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
431→		if err != nil {
432→			h.logger.Debug("skipping path", "path", path, "error", err)
433→			return nil
434→		}
435→
436→		if info.IsDir() {
437→			allowed, checkErr := h.vault.IsPathAllowed(path)
438→			if checkErr != nil || !allowed {
439→				return filepath.SkipDir
440→			}
441→			return nil
442→		}
443→
444→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
445→			return nil
446→		}
447→
448→		allowed, checkErr := h.vault.IsPathAllowed(path)
449→		if checkErr != nil || !allowed {
450→			return nil
451→		}
452→
453→		// Exclude the target note itself
454→		baseName := strings.TrimSuffix(filepath.Base(path), ".md")
455→		if strings.EqualFold(baseName, noteName) {
456→			return nil
457→		}
458→
459→		data, err := os.ReadFile(path)
460→		if err != nil {
461→			h.logger.Debug("skipping unreadable file", "path", path, "error", err)
462→			return nil
463→		}
464→
465→		lines := strings.Split(string(data), "\n")
466→		for _, line := range lines {
467→			matches := wikilinkRe.FindAllStringSubmatch(line, -1)
468→			for _, match := range matches {
469→				if len(match) >= 2 {
470→					linkTarget := strings.TrimSuffix(match[1], ".md")
471→					if strings.EqualFold(linkTarget, noteName) {
472→						results = append(results, note.Backlink{
473→							Path: path,
474→							Line: line,
475→						})
476→						break // one match per line is enough
477→					}
478→				}
479→			}
480→		}
481→
482→		return nil
483→	})
484→
485→	if err != nil {
486→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
487→	}
488→
489→	output := note.GetBacklinksOutput{Results: results}
490→
491→	textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
492→	if len(results) > 0 {
493→		var lines []string
494→		for _, bl := range results {
495→			lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
496→		}
497→		textContent += ":\n" + strings.Join(lines, "\n")
498→	}
499→
500→	result := &mcp.CallToolResult{
501→		Content: []mcp.Content{
502→			&mcp.TextContent{Text: textContent},
503→		},
504→	}
505→	return result, output, nil
506→}
