508→// ListTags implements the list_tags tool
509→func (h *Handler) ListTags(ctx context.Context, req *mcp.CallToolRequest, input note.ListTagsInput) (*mcp.CallToolResult, note.ListTagsOutput, error) {
510→	tagCounts := make(map[string]int)
511→
512→	// Regex for inline #tags (not inside code blocks)
513→	inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
514→
515→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
516→		if err != nil {
517→			h.logger.Debug("skipping path", "path", path, "error", err)
518→			return nil
519→		}
520→
521→		if info.IsDir() {
522→			allowed, checkErr := h.vault.IsPathAllowed(path)
523→			if checkErr != nil || !allowed {
524→				return filepath.SkipDir
525→			}
526→			return nil
527→		}
528→
529→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
530→			return nil
531→		}
532→
533→		allowed, checkErr := h.vault.IsPathAllowed(path)
534→		if checkErr != nil || !allowed {
535→			return nil
536→		}
537→
538→		data, err := os.ReadFile(path)
539→		if err != nil {
540→			h.logger.Debug("skipping unreadable file", "path", path, "error", err)
541→			return nil
542→		}
543→
544→		content := string(data)
545→
546→		// Parse frontmatter tags
547→		if strings.HasPrefix(content, "---\n") {
548→			endIdx := strings.Index(content[4:], "\n---\n")
549→			if endIdx >= 0 {
550→				frontmatter := content[4 : 4+endIdx]
551→				note.ParseFrontmatterTags(frontmatter, tagCounts)
552→			}
553→		}
554→
555→		// Parse inline #tags (skip code blocks)
556→		lines := strings.Split(content, "\n")
557→		inCodeBlock := false
558→		for _, line := range lines {
559→			if strings.HasPrefix(strings.TrimSpace(line), "```") {
560→				inCodeBlock = !inCodeBlock
561→				continue
562→			}
563→			if inCodeBlock {
564→				continue
565→			}
566→			matches := inlineTagRe.FindAllStringSubmatch(line, -1)
567→			for _, match := range matches {
568→				if len(match) >= 2 {
569→					tagCounts[match[1]]++
570→				}
571→			}
572→		}
573→
574→		return nil
575→	})
576→
577→	if err != nil {
578→		return nil, note.ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
579→	}
580→
581→	// Filter by prefix and sort
582→	var tags []note.TagCount
583→	for tag, count := range tagCounts {
584→		if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
585→			tags = append(tags, note.TagCount{Tag: tag, Count: count})
586→		}
587→	}
588→	sort.Slice(tags, func(i, j int) bool {
589→		return tags[i].Tag < tags[j].Tag
590→	})
591→
592→	output := note.ListTagsOutput{Tags: tags}
593→
594→	textContent := fmt.Sprintf("Found %d unique tags", len(tags))
595→	if len(tags) > 0 {
596→		var lines []string
597→		for _, tc := range tags {
598→			lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
599→		}
600→		textContent += ":\n" + strings.Join(lines, "\n")
601→	}
602→
603→	result := &mcp.CallToolResult{
604→		Content: []mcp.Content{
605→			&mcp.TextContent{Text: textContent},
606→		},
607→	}
608→	return result, output, nil
609→}
